def process(tumorSamples, plk1Global, chek2S163Phospho):
    import pandas as pd
    from scipy.stats import spearmanr

    # Inner-join ensures: tumor, in-study, and have both measures (after dropping NAs)
    df = tumorSamples.merge(plk1Global, on='sample_id', how='inner').merge(chek2S163Phospho, on='sample_id', how='inner')

    df = df.dropna(subset=['plk1', 'chek2S163']).copy()

    if len(df) < 2:
        return pd.DataFrame({'n': [len(df)], 'spearman_r': [float('nan')]})

    r, p = spearmanr(df['plk1'], df['chek2S163'])
    return pd.DataFrame({'n': [len(df)], 'spearman_r': [float(r)], 'p_value': [float(p)]})
